#!/usr/bin/env bash
set -euo pipefail

# AUTO-GENERATED by Claude Code
# Purpose: Copy the 1Password master password from gnome-keyring to the clipboard via `.os/cli.py pwd-copy`.
#          Target of the SUPER + SHIFT + P Omarchy keybinding; reports the result as a desktop notification.
# Usage: pwd-copy.sh [--clear-after SECONDS]
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

if output="$(uv run "$SCRIPT_DIR/../../cli.py" pwd-copy "$@" 2>&1)"; then
  notify-send "1Password" "$output"
else
  notify-send -u critical "1Password" "$output"
  exit 1
fi
